import heapq
from collections import Counter

class Solution:
    def rearrangeBarcodes(self, barcodes):
        cnt = Counter(barcodes)
        heap = [(-c, v) for v, c in cnt.items()]
        heapq.heapify(heap)
        res = []
        while len(res) < len(barcodes):
            negc, v = heapq.heappop(heap)
            if res and res[-1] == v:
                negc2, v2 = heapq.heappop(heap)
                res.append(v2)
                if negc2 + 1 < 0:
                    heapq.heappush(heap, (negc2 + 1, v2))
                heapq.heappush(heap, (negc, v))
            else:
                res.append(v)
                if negc + 1 < 0:
                    heapq.heappush(heap, (negc + 1, v))
        return res

