import java.util.*;

class Solution {
    public int[] rearrangeBarcodes(int[] barcodes) {
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int b : barcodes) cnt.merge(b, 1, Integer::sum);
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> b[0] - a[0]);
        for (var e : cnt.entrySet()) pq.offer(new int[]{e.getValue(), e.getKey()});
        int[] res = new int[barcodes.length];
        int i = 0;
        while (i < barcodes.length) {
            int[] top = pq.poll();
            if (i > 0 && res[i - 1] == top[1]) {
                int[] second = pq.poll();
                res[i++] = second[1];
                if (--second[0] > 0) pq.offer(second);
                pq.offer(top);
            } else {
                res[i++] = top[1];
                if (--top[0] > 0) pq.offer(top);
            }
        }
        return res;
    }
}

