var rearrangeBarcodes = function(barcodes) {
    const cnt = new Map();
    for (const b of barcodes) cnt.set(b, (cnt.get(b) || 0) + 1);
    const heap = [...cnt.entries()].sort((a, b) => b[1] - a[1]);
    const res = [];
    while (heap.length) {
        let idx = 0;
        if (res.length && res[res.length - 1] === heap[0][0]) idx = 1;
        const [v, c] = heap[idx];
        res.push(v);
        heap.splice(idx, 1);
        if (c - 1 > 0) {
            heap.push([v, c - 1]);
            heap.sort((a, b) => b[1] - a[1]);
        }
    }
    return res;
};

