from collections import Counter

class Solution:
    def rearrangeBarcodes(self, barcodes):
        n = len(barcodes)
        cnt = Counter(barcodes)
        buckets = [[] for _ in range(n + 1)]
        for v, c in cnt.items():
            buckets[c].append(v)
        res = [0] * n
        i = 0
        for c in range(n, 0, -1):
            for v in buckets[c]:
                for _ in range(c):
                    if i >= n:
                        i = 1
                    res[i] = v
                    i += 2
        return res

